-- ═══════════════════════════════════════════════════════════════════════════
-- CURVA ELEVACIÓN-ÁREA-CAPACIDAD OFICIAL — PRESA LA BOQUILLA (PRE-001)
-- Fecha: 2026-08-23
--
-- Fuente: CONAGUA — 'Tabla EAC a 1 centímetro BOQUILLA.xlsx' (hoja 'Tabla
-- e-a-c 1cm gráfica') y 'CEAC La Boquilla, Chih.xlsx' (clave oficial LBQCH,
-- nombre común 'Lago de Toronto, Chih.', NAMO/NAME). Reemplaza los 14 puntos
-- placeholder cargados anteriormente en curvas_capacidad (valores redondos
-- inventados cada 5m, con una inconsistencia real: el volumen bajaba de
-- 1300→1302.17 msnm — geométricamente imposible en un vaso).
--
-- 5501 puntos a 1cm de resolución real, 1265.00–1319.99 msnm.
-- Reemplaza TODA la curva existente de PRE-001 (DELETE + INSERT) para no
-- dejar puntos placeholder mezclados con los oficiales en la interpolación
-- del simulador de nivel (PresaVasoMonitor.tsx → volumenPorElevacion).
--
-- Referencias oficiales (fuente: CEAC La Boquilla, Chih.xlsx):
--   NAMO (Nivel de Aguas Máximas Ordinario): 1317.00 msnm — 2,893.571 hm³
--   NAME (Nivel de Aguas Máximas Extraordinario): 1319.10 msnm — 3,278.098 hm³
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;

DELETE FROM public.curvas_capacidad WHERE presa_id = 'PRE-001';

